import { CONFIG_SQL } from "./sql/config.sql.js";
// src/vendor/postgres-meta/lib/PostgresMetaConfig.ts
var PostgresMetaConfig = class {
	constructor(query) {
		this.query = query;
	}
	async list({ limit, offset } = {}) {
		const sql = CONFIG_SQL({
			limit,
			offset
		});
		return await this.query(sql);
	}
};
export { PostgresMetaConfig as default };
